    public void testRemoveRow_ValidKey() {
        Comparable rowKey = (Comparable) "Row1";
        Comparable colKey = (Comparable) "Col1";
        dataset.addObject("Data", rowKey, colKey);

        int initialRowCount = dataset.getRowCount();
        assertEquals(1, initialRowCount);

        dataset.removeRow(rowKey);

        assertEquals(0, dataset.getRowCount());
    }

